<?php $this->layout('layouts/studio'); ?>
<section class="studio-page-header"><div><small>BLOG</small><h2>Artigos</h2><p>Crie, revise e publique o conteúdo do site.</p></div><div class="actions"><a class="studio-btn" href="<?= url('/operation/blog/categories') ?>"><ion-icon name="folder-outline"></ion-icon>Categorias</a><a class="studio-btn primary" href="<?= url('/operation/blog/post') ?>"><ion-icon name="add-outline"></ion-icon>Novo artigo</a></div></section>
