    <header><div><h2>Lista de artigos</h2><small>Conteúdos cadastrados no blog</small></div><form class="studio-list-filter ajax_off" action="<?= url('/operation/blog/home') ?>" method="post"><label><ion-icon name="search-outline"></ion-icon><input name="s" value="<?= htmlspecialchars($search) ?>" placeholder="Buscar por título"></label><button class="studio-btn" type="submit">Buscar</button></form></header>
